function validate([rooms]) {
  if (!Array.isArray(rooms) || rooms.length < 2 || rooms.length > 1000) return 'rooms needs 2 to 1000 rooms.';
  const n = rooms.length;
  let total = 0;
  for (const keys of rooms) {
    if (!Array.isArray(keys) || keys.length > 1000) return 'Each room holds at most 1000 keys.';
    total += keys.length;
    if (keys.some(k => !Number.isInteger(k) || k < 0 || k >= n)) return 'Each key is a room number from 0 to n - 1.';
    if (new Set(keys).size !== keys.length) return 'The keys inside one room must be distinct.';
  }
  if (total < 1 || total > 3000) return 'There are 1 to 3000 keys in total.';
  return null;
}

