function canVisitAllRooms(rooms) {
  const visited = new Array(rooms.length).fill(false);
  const stack = [0];
  visited[0] = true;
  let count = 1;

  while (stack.length > 0) {
    const room = stack.pop();
    for (const key of rooms[room]) {
      if (!visited[key]) {
        visited[key] = true;
        count++;
        stack.push(key);
      }
    }
  }
  return count === rooms.length;
}

