function generate(rand, size) {
  const n = size === 'large' ? 600 + Math.floor(rand() * 401) : 2 + Math.floor(rand() * 6);
  const sets = Array.from({ length: n }, () => new Set());
  const budget = size === 'large' ? 3000 : 3 * n;
  let total = 0;
  if (rand() < 0.6) {
    // Spread a random spanning tree from room 0 so that every room is reachable.
    const order = [0];
    const rest = Array.from({ length: n - 1 }, (_, i) => i + 1);
    for (let i = rest.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [rest[i], rest[j]] = [rest[j], rest[i]]; }
    for (const room of rest) {
      const holder = order[Math.floor(rand() * order.length)];
      sets[holder].add(room);
      order.push(room);
      total++;
    }
  }
  const extra = Math.floor(rand() * (budget - total + 1) * (size === 'large' ? 0.5 : 0.6));
  for (let e = 0; e < extra; e++) {
    const from = Math.floor(rand() * n);
    const to = Math.floor(rand() * n);
    if (!sets[from].has(to)) { sets[from].add(to); total++; }
  }
  if (rand() < 0.3) {
    // Lock one room for good by removing every key to it.
    const target = 1 + Math.floor(rand() * (n - 1));
    for (let i = 0; i < n; i++) if (i !== target && sets[i].delete(target)) total--;
  }
  if (total === 0) sets[n - 1].add(0);
  return [sets.map(s => [...s])];
}
